import React, { useState, useEffect } from 'react';
import './Registro.css';

function Registro() {
  const [formData, setFormData] = useState({
    nombre: '',
    apellido: '',
    dni: '',
    email: '',
    nro_celular: '',
    calle: '',
    nro_calle: '',
    cod_postal: '',
    id_localidad: '', // Ahora guardaremos el nombre de la localidad aquí
    password: '',
  });

  const [localidades, setLocalidades] = useState([]);

  useEffect(() => {
    // Consumiendo la API para obtener localidades
    const fetchLocalidades = async () => {
      try {
        const response = await fetch('https://apis.datos.gob.ar/georef/api/localidades?provincia=18');
        const data = await response.json();
        setLocalidades(data.localidades); // Guardamos las localidades en el estado
      } catch (error) {
        console.error('Error al obtener localidades:', error);
      }
    };

    fetchLocalidades();
  }, []); // Esto solo se ejecuta una vez al montar el componente

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prevData => ({
      ...prevData,
      [name]: value
    }));
  };

  const handleLocalidadChange = (e) => {
    // Cambiar para almacenar el nombre de la localidad en vez del id
    const localidadSeleccionada = e.target.value;
    setFormData(prevData => ({
      ...prevData,
      id_localidad: localidadSeleccionada, // Guardar solo el nombre
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      // Enviar los datos de usuario junto con la dirección y localidad seleccionada
      const response = await fetch('http://localhost:4000/api/auth/register', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(formData)
      });

      if (response.ok) {
        alert('¡Usuario registrado exitosamente!');
      } else {
        alert('Hubo un error al registrar el usuario.');
      }
    } catch (error) {
      console.error('Error en el registro:', error);
    }
  };

  return (
    <div className="registro-container">
      <div className="registro-form">
        <h2>Crear Cuenta</h2>
        <form onSubmit={handleSubmit}>
          <input
            type="text"
            name="nombre"
            placeholder="Nombre"
            value={formData.nombre}
            onChange={handleChange}
            required
          />
          <input
            type="text"
            name="apellido"
            placeholder="Apellido"
            value={formData.apellido}
            onChange={handleChange}
            required
          />
          <input
            type="text"
            name="dni"
            placeholder="DNI"
            value={formData.dni}
            onChange={handleChange}
            required
          />
          <input
            type="email"
            name="email"
            placeholder="Correo electrónico"
            value={formData.email}
            onChange={handleChange}
            required
          />
          <input
            type="text"
            name="nro_celular"
            placeholder="Número de celular"
            value={formData.nro_celular}
            onChange={handleChange}
            required
          />

          {/* Campo de Localidad con datos obtenidos de la API */}
          <select
            name="id_localidad"
            value={formData.id_localidad}
            onChange={handleLocalidadChange} // Usamos la nueva función para manejar el nombre
            required
            className="custom-select"
          >
            <option value="">Seleccione una localidad</option>
            {localidades.map((localidad) => (
              <option key={localidad.id} value={localidad.nombre}>
                {localidad.nombre}
              </option>
            ))}
          </select>

          {/* Campos de Dirección */}
          <input
            type="text"
            name="calle"
            placeholder="Calle"
            value={formData.calle}
            onChange={handleChange}
            required
          />
          <input
            type="text"
            name="nro_calle"
            placeholder="Número de calle"
            value={formData.nro_calle}
            onChange={handleChange}
            required
          />
          <input
            type="text"
            name="cod_postal"
            placeholder="Código Postal"
            value={formData.cod_postal}
            onChange={handleChange}
            required
          />

          <input
            type="password"
            name="password"
            placeholder="Contraseña"
            value={formData.password}
            onChange={handleChange}
            required
          />
          <button type="submit">Registrarse</button>
        </form>
      </div>
    </div>
  );
}

export default Registro;
